using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.FNZ.DocumentosTransaccion;namespace GraphApi.Services.FNZ.DocumentosTransaccion{    public class DocumentosTransaccionService : IDocumentosTransaccionService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public DocumentosTransaccionService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadDocumentosTransaccion>> GetDocumentosTransaccions(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM fnz.DocumentosTransaccion (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadDocumentosTransaccion>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetDocumentosTransaccionsDynamic(            int? documentoTransaccionID,            int? transaccionID,            int? documentoID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "DocumentoTransaccionID, TransaccionID, DocumentoID, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM fnz.DocumentosTransaccion (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (documentoTransaccionID.HasValue)            {                vSql.Append(" AND DocumentoTransaccionID = @DocumentoTransaccionID");                vParameters.Add("DocumentoTransaccionID",documentoTransaccionID);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadDocumentosTransaccion> CreateDocumentosTransaccion(clCreateDocumentosTransaccion objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO fnz.DocumentosTransaccion                (TransaccionID, DocumentoID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TransaccionID, @DocumentoID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TransaccionID,                objInput.DocumentoID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT DocumentoTransaccionID, TransaccionID, DocumentoID, bEliminado                FROM fnz.DocumentosTransaccion (NOLOCK)                WHERE DocumentoTransaccionID = @DocumentoTransaccionID;";            var vReadParams = new { DocumentoTransaccionID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadDocumentosTransaccion>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el DocumentosTransaccion con ID {vNewId}.");            return vCreated;        }        public async Task<clReadDocumentosTransaccion?> UpdateDocumentosTransaccion(clUpdateDocumentosTransaccion objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("DocumentoTransaccionID", objInput.DocumentoTransaccionID);            if (objInput.TransaccionID != null)            {                vSets.Add("TransaccionID = @TransaccionID");                vParameters.Add("TransaccionID", objInput.TransaccionID);            }            if (objInput.DocumentoID != null)            {                vSets.Add("DocumentoID = @DocumentoID");                vParameters.Add("DocumentoID", objInput.DocumentoID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE fnz.DocumentosTransaccion                SET {vSetClause}                WHERE DocumentoTransaccionID = @DocumentoTransaccionID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT DocumentoTransaccionID, TransaccionID, DocumentoID, bEliminado                FROM fnz.DocumentosTransaccion (NOLOCK)                WHERE DocumentoTransaccionID = @DocumentoTransaccionID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadDocumentosTransaccion>(sSelect, new {  objInput.DocumentoTransaccionID });        }        public async Task<bool> DeleteDocumentosTransaccion(int nDocumentosTransaccionID)        {            const string sSql = @"                DELETE FROM fnz.DocumentosTransaccion                WHERE DocumentoTransaccionID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nDocumentosTransaccionID });            return vAffected > 0;        }    }}